-- Merck Spectroquant® Prove plus spectrophotometers (100 plus, 300 plus, 600 plus) from the Merck technical data sheets.
-- Run once in Supabase -> SQL Editor (choose "Run without RLS" if asked). Safe to run again.
alter table products add column if not exists features jsonb not null default '[]'::jsonb;
insert into brands (name, slug, website_url) values ('Merck', 'merck', 'https://www.sigmaaldrich.com/')
on conflict (slug) do nothing;
insert into categories (name, slug, sort_order) values ('Spectrophotometer', 'spectrophotometer', 7) on conflict (slug) do nothing;

insert into products (sku, name, slug, description, specs, features, category_id, brand_id, image_url, is_active)
select v.sku, v.name, v.slug, v.description, v.specs::jsonb, v.features::jsonb, c.id, b.id, v.image_url, true
from (values
  ('MERCK-1.73026.0001', 'Merck Spectroquant® Prove 100 plus Spectrophotometer', 'merck-spectroquant-prove-100-plus-spectrophotometer', 'Spectroquant® Prove 100 plus is a VIS spectrophotometer (320 – 1,100 nm) with reference beam technology for water, wastewater, food and beverage analysis. It reads all Spectroquant® cell and reagent tests automatically by 2-D barcode, with built-in analytical quality assurance.', '[["Model", "Spectroquant® Prove 100 plus"], ["Catalogue No.", "1.73026.0001"], ["Measuring technology", "Spectrophotometer with reference beam technology"], ["Wavelength range", "320 – 1,100 nm"], ["Lamp", "Tungsten halogen lamp"], ["Detector", "Silicon photo diode"], ["Measuring modes", "Concentration, absorbance, transmission, multi-wavelength, spectra and kinetics"], ["Spectral bandwidth", "4 nm"], ["Wavelength reproducibility", "± 0.2 nm"], ["Wavelength accuracy", "± 1 nm"], ["Stray light", "≤ 0.1% T at 340 nm"], ["Photometric range", "± 3.0 Abs"], ["Absorbance resolution", "0.001 Abs"], ["Absorbance reproducibility", "± 0.003 Abs at 1 Abs (320 – 900 nm)"], ["Absorbance accuracy", "at 340 – 900 nm: ± 0.005 Abs at 1 and 2 Abs; ± 0.010 Abs at 2.5 Abs"], ["Scan speed", "up to 170 nm/min (increment 0.1 / 1 / 5 nm)"], ["Cells", "16 mm round; 10, 20 and 50 mm rectangular (automatic recognition)"], ["Power consumption", "12 W standard, 8.8 W power save, 55.2 W measuring"], ["Wavelength resolution", "1 nm (scan 0.1 nm)"], ["Smart screen display", "p-cap glass touch screen"], ["Live ID barcode", "Automatic 2-D barcode reading for all Spectroquant® cell and reagent tests (lot, expiry and calibration data stored with each measurement)"], ["Cell holder", "Removable for easy cleaning"], ["Methods", "All Spectroquant® cell and reagent tests programmed; user-defined: 99 concentration, 20 kinetic, 20 wavelength scans"], ["Applications", "Free pre-programmed: bromate, brewery (MEBAK/EBC), sugar (ICUMSA®), oil (DOBI, olive oil)"], ["Ambient light protection", "Measurement with open shaft possible"], ["AQA prime", "AQA1 instrument check (PhotoCheck / Certipur® standards), AQA2 system check (CombiCheck / standard solutions)"], ["Monitoring functions", "Pipette check and sample matrix check"], ["Interfaces", "2 × USB-A, 1 × USB-mini-B, Ethernet (LAN)"], ["Data storage", "7,000 single measured values; 500 records each of spectra, kinetics, AQA1 and AQA2"], ["Languages", "28 languages incl. English, Malay, Chinese, Indonesian, Thai and Vietnamese"], ["Protection class", "IP 31 for optics and electronics"], ["Power requirements", "100 – 230 V, 50 – 60 Hz (US, EU, UK and China plug cables included)"], ["Operating conditions", "10 – 35 °C, 20 – 80% rH non-condensing"], ["Dimensions (W × D × H)", "418 × 278 × 169 mm"], ["Weight", "approx. 6.8 kg"], ["Warranty", "24 months"]]', '["VIS range 320 – 1,100 nm with tungsten halogen lamp", "Reference beam technology for stable results", "Live ID: automatic 2-D barcode reading of Spectroquant® tests", "Measure with the cell shaft open (ambient light protection)", "AQA prime analytical quality assurance with pipette and sample matrix checks", "Glass touch screen; USB, LAN and free software/method updates"]', '/products/merck/prove-100-plus.jpg'),
  ('MERCK-1.73027.0001', 'Merck Spectroquant® Prove 300 plus Spectrophotometer', 'merck-spectroquant-prove-300-plus-spectrophotometer', 'Spectroquant® Prove 300 plus is a UV-VIS spectrophotometer (190 – 1,100 nm) with a xenon flash lamp and reference beam technology, covering UV methods as well as all Spectroquant® cell and reagent tests, with automatic 2-D barcode recognition and built-in analytical quality assurance.', '[["Model", "Spectroquant® Prove 300 plus"], ["Catalogue No.", "1.73027.0001"], ["Measuring technology", "Spectrophotometer with reference beam technology"], ["Wavelength range", "190 – 1,100 nm (UV-VIS)"], ["Lamp", "Xenon flash lamp"], ["Detector", "Silicon photo diode"], ["Measuring modes", "Concentration, absorbance, transmission, multi-wavelength, spectra and kinetics"], ["Spectral bandwidth", "4 nm"], ["Wavelength reproducibility", "± 0.2 nm"], ["Wavelength accuracy", "± 1 nm"], ["Stray light", "≤ 0.1% T at 340 nm; ≤ 1% T at 198 nm"], ["Photometric range", "± 3.0 Abs"], ["Absorbance resolution", "0.001 Abs"], ["Absorbance reproducibility", "± 0.003 Abs at 1 Abs (200 – 900 nm)"], ["Absorbance accuracy", "at 300 – 900 nm: ± 0.005 Abs at 1 and 2 Abs; ± 0.008 Abs at 2.5 Abs"], ["Scan speed", "up to 750 nm/min (increment 0.1 / 1 / 5 nm)"], ["Cells", "16 mm round; 10, 20 and 50 mm rectangular (automatic recognition)"], ["Power consumption", "12 W standard, 8.6 W power save, 46.5 W measuring"], ["Wavelength resolution", "1 nm (scan 0.1 nm)"], ["Smart screen display", "p-cap glass touch screen"], ["Live ID barcode", "Automatic 2-D barcode reading for all Spectroquant® cell and reagent tests (lot, expiry and calibration data stored with each measurement)"], ["Cell holder", "Removable for easy cleaning"], ["Methods", "All Spectroquant® cell and reagent tests programmed; user-defined: 99 concentration, 20 kinetic, 20 wavelength scans"], ["Applications", "Free pre-programmed: bromate, brewery (MEBAK/EBC), sugar (ICUMSA®), oil (DOBI, olive oil)"], ["Ambient light protection", "Measurement with open shaft possible"], ["AQA prime", "AQA1 instrument check (PhotoCheck / Certipur® standards), AQA2 system check (CombiCheck / standard solutions)"], ["Monitoring functions", "Pipette check and sample matrix check"], ["Interfaces", "2 × USB-A, 1 × USB-mini-B, Ethernet (LAN)"], ["Data storage", "7,000 single measured values; 500 records each of spectra, kinetics, AQA1 and AQA2"], ["Languages", "28 languages incl. English, Malay, Chinese, Indonesian, Thai and Vietnamese"], ["Protection class", "IP 31 for optics and electronics"], ["Power requirements", "100 – 230 V, 50 – 60 Hz (US, EU, UK and China plug cables included)"], ["Operating conditions", "10 – 35 °C, 20 – 80% rH non-condensing"], ["Dimensions (W × D × H)", "418 × 278 × 169 mm"], ["Weight", "approx. 6.8 kg"], ["Warranty", "24 months"]]', '["UV-VIS range 190 – 1,100 nm with xenon flash lamp", "Fast scanning up to 750 nm/min", "Reference beam technology for stable results", "Live ID: automatic 2-D barcode reading of Spectroquant® tests", "Measure with the cell shaft open (ambient light protection)", "AQA prime analytical quality assurance with pipette and sample matrix checks", "Glass touch screen; USB, LAN and free software/method updates"]', '/products/merck/prove-300-plus.jpg'),
  ('MERCK-1.73028.0001', 'Merck Spectroquant® Prove 600 plus Spectrophotometer', 'merck-spectroquant-prove-600-plus-spectrophotometer', 'Spectroquant® Prove 600 plus is the top UV-VIS model (190 – 1,100 nm) with a narrow 1.8 nm spectral bandwidth for pharmacopoeia-grade measurements, 100 mm cell support and ± 3.3 Abs range, plus automatic 2-D barcode recognition of all Spectroquant® tests.', '[["Model", "Spectroquant® Prove 600 plus"], ["Catalogue No.", "1.73028.0001"], ["Measuring technology", "Spectrophotometer with reference beam technology"], ["Wavelength range", "190 – 1,100 nm (UV-VIS)"], ["Lamp", "Xenon flash lamp"], ["Detector", "Silicon photo diode"], ["Measuring modes", "Concentration, absorbance, transmission, multi-wavelength, spectra and kinetics"], ["Spectral bandwidth", "1.8 nm (toluene/hexane ratio > 1.4)"], ["Wavelength reproducibility", "± 0.1 nm"], ["Wavelength accuracy", "± 1 nm"], ["Stray light", "≤ 0.1% T at 340 nm; ≤ 1% T at 198 nm"], ["Photometric range", "± 3.3 Abs"], ["Absorbance resolution", "0.001 Abs"], ["Absorbance reproducibility", "± 0.003 Abs at 1 Abs (200 – 900 nm)"], ["Absorbance accuracy", "at 230 – 900 nm: ± 0.004 Abs at 1 and 2 Abs; ± 0.006 Abs at 2.5 Abs"], ["Scan speed", "up to 750 nm/min (increment 0.1 / 1 / 5 nm)"], ["Cells", "16 mm round; 10, 20, 50 and 100 mm rectangular (automatic recognition)"], ["Power consumption", "12 W standard, 8.6 W power save, 46.5 W measuring"], ["Wavelength resolution", "1 nm (scan 0.1 nm)"], ["Smart screen display", "p-cap glass touch screen"], ["Live ID barcode", "Automatic 2-D barcode reading for all Spectroquant® cell and reagent tests (lot, expiry and calibration data stored with each measurement)"], ["Cell holder", "Removable for easy cleaning"], ["Methods", "All Spectroquant® cell and reagent tests programmed; user-defined: 99 concentration, 20 kinetic, 20 wavelength scans"], ["Applications", "Free pre-programmed: bromate, brewery (MEBAK/EBC), sugar (ICUMSA®), oil (DOBI, olive oil)"], ["Ambient light protection", "Measurement with open shaft possible"], ["AQA prime", "AQA1 instrument check (PhotoCheck / Certipur® standards), AQA2 system check (CombiCheck / standard solutions)"], ["Monitoring functions", "Pipette check and sample matrix check"], ["Interfaces", "2 × USB-A, 1 × USB-mini-B, Ethernet (LAN)"], ["Data storage", "7,000 single measured values; 500 records each of spectra, kinetics, AQA1 and AQA2"], ["Languages", "28 languages incl. English, Malay, Chinese, Indonesian, Thai and Vietnamese"], ["Protection class", "IP 31 for optics and electronics"], ["Power requirements", "100 – 230 V, 50 – 60 Hz (US, EU, UK and China plug cables included)"], ["Operating conditions", "10 – 35 °C, 20 – 80% rH non-condensing"], ["Dimensions (W × D × H)", "418 × 278 × 169 mm"], ["Weight", "approx. 6.8 kg"], ["Warranty", "24 months"]]', '["UV-VIS range 190 – 1,100 nm with 1.8 nm bandwidth for pharmacopoeia requirements", "Supports 100 mm rectangular cells for very low concentrations", "Fast scanning up to 750 nm/min", "Reference beam technology for stable results", "Live ID: automatic 2-D barcode reading of Spectroquant® tests", "Measure with the cell shaft open (ambient light protection)", "AQA prime analytical quality assurance with pipette and sample matrix checks", "Glass touch screen; USB, LAN and free software/method updates"]', '/products/merck/prove-600-plus.jpg')
) as v(sku, name, slug, description, specs, features, image_url)
cross join (select id from categories where slug = 'spectrophotometer') c
cross join (select id from brands where slug = 'merck') b
on conflict (sku) do update set name = excluded.name, slug = excluded.slug, description = excluded.description, specs = excluded.specs,
  features = excluded.features, category_id = excluded.category_id, brand_id = excluded.brand_id, image_url = excluded.image_url, is_active = true;

select name, sku from products where sku like 'MERCK-1.7302%' order by sku;
